def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    def segments(length, separators):
        result, start = [], 0
        for i in separators:
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < length:
            result.append((start, length))
        return result

    row_parts = segments(h, sep_rows)
    col_parts = segments(w, sep_cols)

    source = max(
        ((ri, ci) for ri in range(len(row_parts))
         for ci in range(len(col_parts))),
        key=lambda p: sum(
            grid[r][c] != background
            for r in range(*row_parts[p[0]])
            for c in range(*col_parts[p[1]])
        )
    )
    sr0, sr1 = row_parts[source[0]]
    sc0, sc1 = col_parts[source[1]]
    out = [row[:] for row in grid]

    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = grid[sr0 + (r - r0)][sc0 + (c - c0)]

    return out
